def import_string(import_name: str, silent: bool = False) -> t.Any:
    """Imports an object based on a string.  This is useful if you want to
    use import paths as endpoints or something similar.  An import path can
    be specified either in dotted notation (``xml.sax.saxutils.escape``)
    or with a colon as object delimiter (``xml.sax.saxutils:escape``).

    If the `silent` is True the return value will be `None` if the import
    fails.

    :return: imported object
    """
    try:
        if ":" in import_name:
            module, obj = import_name.split(":", 1)
        elif "." in import_name:
            module, _, obj = import_name.rpartition(".")
        else:
            return __import__(import_name)
        return getattr(__import__(module, None, None, [obj]), obj)
    except (ImportError, AttributeError):
        if not silent:
            raise

def lexer(self) -> Lexer:
    """The lexer for this environment."""
    return get_lexer(self)

def get(self, key: t.Any, default: t.Any = None) -> t.Any:
    """Return an item from the cache dict or `default`"""
    try:
        return self[key]
    except KeyError:
        return default

def iter_extensions(self) -> t.Iterator["Extension"]:
    """Iterates over the extensions by priority."""
    return iter(sorted(self.extensions.values(), key=lambda x: x.priority))

def getattr(self, obj: t.Any, attribute: str) -> t.Any:
    """Get an item or attribute of an object but prefer the attribute.
    Unlike :meth:`getitem` the attribute *must* be a string.
    """
    try:
        return getattr(obj, attribute)
    except AttributeError:
        pass
    try:
        return obj[attribute]
    except (TypeError, LookupError, AttributeError):
        return self.undefined(obj=obj, name=attribute)

def func(item: t.Any) -> t.Any:
    return context.environment.call_filter(
        name, item, args, kwargs, context=context
    )

def test_filter(env: "Environment", value: str) -> bool:
    """Check if a filter exists by name. Useful if a filter may be
    optionally available.

    .. code-block:: jinja

        {% if 'markdown' is filter %}
            {{ value | markdown }}
        {% else %}
            {{ value }}
        {% endif %}

    .. versionadded:: 3.0
    """
    return value in env.filters

def test_test(env: "Environment", value: str) -> bool:
    """Check if a test exists by name. Useful if a test may be
    optionally available.

    .. code-block:: jinja

        {% if 'loud' is test %}
            {% if value is loud %}
                {{ value|upper }}
            {% else %}
                {{ value|lower }}
            {% endif %}
        {% else %}
            {{ value }}
        {% endif %}

    .. versionadded:: 3.0
    """
    return value in env.tests

def write_file(filename: str, data: str) -> None:
    if zip:
        info = ZipInfo(filename)
        info.external_attr = 0o755 << 16
        zip_file.writestr(info, data)
    else:
        with open(os.path.join(target, filename), "wb") as f:
            f.write(data.encode("utf8"))

def eos(self) -> bool:
    """Are we at the end of the stream?"""
    return not self

def render(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This method accepts the same arguments as the `dict` constructor:
    A dict, a dict subclass or some keyword arguments.  If no arguments
    are given the context will be empty.  These two calls do the same::

        template.render(knights='that say nih')
        template.render({'knights': 'that say nih'})

    This will return the rendered template as a string.
    """
    if self.environment.is_async:
        import asyncio

        close = False

        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = asyncio.new_event_loop()
            close = True

        try:
            return loop.run_until_complete(self.render_async(*args, **kwargs))
        finally:
            if close:
                loop.close()

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(self.root_render_func(ctx))  # type: ignore
    except Exception:
        self.environment.handle_exception()

async def render_async(self, *args: t.Any, **kwargs: t.Any) -> str:
    """This works similar to :meth:`render` but returns a coroutine
    that when awaited returns the entire rendered template string.  This
    requires the async feature to be enabled.

    Example usage::

        await template.render_async(knights='that say nih; asynchronously')
    """
    if not self.environment.is_async:
        raise RuntimeError(
            "The environment was not created with async mode enabled."
        )

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment.concat(  # type: ignore
            [n async for n in self.root_render_func(ctx)]  # type: ignore
        )
    except Exception:
        return self.environment.handle_exception()

def render(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
    """Render the template to produce a native Python type. If the
    result is a single node, its value is returned. Otherwise, the
    nodes are concatenated as strings. If the result can be parsed
    with :func:`ast.literal_eval`, the parsed value is returned.
    Otherwise, the string is returned.
    """
    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment_class.concat(  # type: ignore
            self.root_render_func(ctx)  # type: ignore
        )
    except Exception:
        return self.environment.handle_exception()

async def render_async(self, *args: t.Any, **kwargs: t.Any) -> t.Any:
    if not self.environment.is_async:
        raise RuntimeError(
            "The environment was not created with async mode enabled."
        )

    ctx = self.new_context(dict(*args, **kwargs))

    try:
        return self.environment_class.concat(  # type: ignore
            [n async for n in self.root_render_func(ctx)]  # type: ignore
        )
    except Exception:
        return self.environment.handle_exception()

def is_up_to_date(self) -> bool:
    """If this variable is `False` there is a newer version available."""
    if self._uptodate is None:
        return True
    return self._uptodate()

def _from_namespace(
    cls,
    environment: Environment,
    namespace: t.MutableMapping[str, t.Any],
    globals: t.MutableMapping[str, t.Any],

def stream(self, *args: t.Any, **kwargs: t.Any) -> "TemplateStream":
    """Works exactly like :meth:`generate` but returns a
    :class:`TemplateStream`.
    """
    return TemplateStream(self.generate(*args, **kwargs))

def parse(self, parser: "Parser") -> t.Union[nodes.Break, nodes.Continue]:
    token = next(parser.stream)
    if token.value == "break":
        return nodes.Break(lineno=token.lineno)
    return nodes.Continue(lineno=token.lineno)

def _get_default_module(self, ctx: t.Optional[Context] = None) -> "TemplateModule":
    """If a context is passed in, this means that the template was
    imported. Imported templates have access to the current
    template's globals by default, but they can only be accessed via
    the context during runtime.

    If there are new globals, we need to create a new module because
    the cached module is already rendered and will not have access
    to globals from the current context. This new module is not
    cached because the template can be imported elsewhere, and it
    should have access to only the current template's globals.
    """
    if self.environment.is_async:
        raise RuntimeError("Module is not available in async mode.")

    if ctx is not None:
        keys = ctx.globals_keys - self.globals.keys()

        if keys:
            return self.make_module({k: ctx.parent[k] for k in keys})

    if self._module is None:
        self._module = self.make_module()

    return self._module

def get_corresponding_lineno(self, lineno: int) -> int:
    """Return the source line number of a line number in the
    generated bytecode as they are not in sync.
    """
    for template_line, code_line in reversed(self.debug_info):
        if code_line <= lineno:
            return template_line
    return 1

def debug_info(self) -> t.List[t.Tuple[int, int]]:
    """The debug info mapping."""
    if self._debug_info:
        return [
            tuple(map(int, x.split("=")))  # type: ignore
            for x in self._debug_info.split("&")
        ]

    return []

def get_template_locals(real_locals: t.Mapping[str, t.Any]) -> t.Dict[str, t.Any]:
    """Based on the runtime locals, get the context that would be
    available at that point in the template.
    """
    # Start with the current template context.
    ctx: "t.Optional[Context]" = real_locals.get("context")

    if ctx is not None:
        data: t.Dict[str, t.Any] = ctx.get_all().copy()
    else:
        data = {}

    # Might be in a derived context that only sets local variables
    # rather than pushing a context. Local variables follow the scheme
    # l_depth_name. Find the highest-depth local that has a value for
    # each name.
    local_overrides: t.Dict[str, t.Tuple[int, t.Any]] = {}

    for name, value in real_locals.items():
        if not name.startswith("l_") or value is missing:
            # Not a template variable, or no longer relevant.
            continue

        try:
            _, depth_str, name = name.split("_", 2)
            depth = int(depth_str)
        except ValueError:
            continue

        cur_depth = local_overrides.get(name, (-1,))[0]

        if cur_depth < depth:
            local_overrides[name] = (depth, value)

    # Modify the context with any derived context.
    for name, (_, value) in local_overrides.items():
        if value is missing:
            data.pop(name, None)
        else:
            data[name] = value

    return data

def get_exported(self) -> t.Dict[str, t.Any]:
    """Get a new dict with the exported variables."""
    return {k: self.vars[k] for k in self.exported_vars}

def consume(iterable: t.Iterable[t.Any]) -> None:
    """Consumes an iterable without doing anything with it."""
    for _ in iterable:
        pass

def __next__(self) -> Token:
    """Go one token ahead and return the old one.

    Use the built-in :func:`next` instead of calling this directly.
    """
    rv = self.current

    if self._pushed:
        self.current = self._pushed.popleft()
    elif self.current.type is not TOKEN_EOF:
        try:
            self.current = next(self._iter)
        except StopIteration:
            self.close()

    return rv

def _buffered_generator(self, size: int) -> t.Iterator[str]:
    buf: t.List[str] = []
    c_size = 0
    push = buf.append

    while True:
        try:
            while c_size < size:
                c = next(self._gen)
                push(c)
                if c:
                    c_size += 1
        except StopIteration:
            if not c_size:
                return
        yield concat(buf)
        del buf[:]
        c_size = 0

def enable_buffering(self, size: int = 5) -> None:
    """Enable buffering.  Buffer `size` items before yielding them."""
    if size <= 1:
        raise ValueError("buffer size too small")

    self.buffered = True
    self._next = partial(next, self._buffered_generator(size))

def list_templates(self) -> t.List[str]:
    found = set()
    for searchpath in self.searchpath:
        walk_dir = os.walk(searchpath, followlinks=self.followlinks)
        for dirpath, _, filenames in walk_dir:
            for filename in filenames:
                template = (
                    os.path.join(dirpath, filename)[len(searchpath) :]
                    .strip(os.path.sep)
                    .replace(os.path.sep, "/")
                )
                if template[:2] == "./":
                    template = template[2:]
                if template not in found:
                    found.add(template)
    return sorted(found)

def list_templates(self) -> t.List[str]:
    results: t.List[str] = []

    if self._archive is None:
        # Package is a directory.
        offset = len(self._template_root)

        for dirpath, _, filenames in os.walk(self._template_root):
            dirpath = dirpath[offset:].lstrip(os.path.sep)
            results.extend(
                os.path.join(dirpath, name).replace(os.path.sep, "/")
                for name in filenames
            )
    else:
        if not hasattr(self._loader, "_files"):
            raise TypeError(
                "This zip import does not have the required"
                " metadata to list templates."
            )

        # Package is a zip file.
        prefix = (
            self._template_root[len(self._archive) :].lstrip(os.path.sep)
            + os.path.sep
        )
        offset = len(prefix)

        for name in self._loader._files.keys():  # type: ignore
            # Find names under the templates directory that aren't directories.
            if name.startswith(prefix) and name[-1] != os.path.sep:
                results.append(name[offset:].replace(os.path.sep, "/"))

    results.sort()
    return results

def list_templates(self) -> t.List[str]:
    result = []
    for prefix, loader in self.mapping.items():
        for template in loader.list_templates():
            result.append(prefix + self.delimiter + template)
    return result

def list_templates(self) -> t.List[str]:
    found = set()
    for loader in self.loaders:
        found.update(loader.list_templates())
    return sorted(found)

def is_internal_attribute(obj: t.Any, attr: str) -> bool:
    """Test if the attribute given is an internal python attribute.  For
    example this function returns `True` for the `func_code` attribute of
    python objects.  This is useful if the environment method
    :meth:`~SandboxedEnvironment.is_safe_attribute` is overridden.

    >>> from jinja2.sandbox import is_internal_attribute
    >>> is_internal_attribute(str, "mro")
    True
    >>> is_internal_attribute(str, "upper")
    False
    """
    if isinstance(obj, types.FunctionType):
        if attr in UNSAFE_FUNCTION_ATTRIBUTES:
            return True
    elif isinstance(obj, types.MethodType):
        if attr in UNSAFE_FUNCTION_ATTRIBUTES or attr in UNSAFE_METHOD_ATTRIBUTES:
            return True
    elif isinstance(obj, type):
        if attr == "mro":
            return True
    elif isinstance(obj, (types.CodeType, types.TracebackType, types.FrameType)):
        return True
    elif isinstance(obj, types.GeneratorType):
        if attr in UNSAFE_GENERATOR_ATTRIBUTES:
            return True
    elif hasattr(types, "CoroutineType") and isinstance(obj, types.CoroutineType):
        if attr in UNSAFE_COROUTINE_ATTRIBUTES:
            return True
    elif hasattr(types, "AsyncGeneratorType") and isinstance(
        obj, types.AsyncGeneratorType
    ):
        if attr in UNSAFE_ASYNC_GENERATOR_ATTRIBUTES:
            return True
    return attr.startswith("__")

def getattr(self, obj: t.Any, attribute: str) -> t.Union[t.Any, Undefined]:
    """Subscribe an object from sandboxed code and prefer the
    attribute.  The attribute passed *must* be a bytestring.
    """
    try:
        value = getattr(obj, attribute)
    except AttributeError:
        try:
            return obj[attribute]
        except (TypeError, LookupError):
            pass
    else:
        if self.is_safe_attribute(obj, attribute, value):
            return value
        return self.unsafe_undefined(obj, attribute)
    return self.undefined(obj=obj, name=attribute)

def unsafe_undefined(self, obj: t.Any, attribute: str) -> Undefined:
    """Return an undefined object for unsafe attributes."""
    return self.undefined(
        f"access to attribute {attribute!r} of"
        f" {type(obj).__name__!r} object is unsafe.",
        name=attribute,
        obj=obj,
        exc=SecurityError,
    )

def markup_join(seq: t.Iterable[t.Any]) -> str:
    """Concatenation that escapes if necessary and converts to string."""
    buf = []
    iterator = map(soft_str, seq)
    for arg in iterator:
        buf.append(arg)
        if hasattr(arg, "__html__"):
            return Markup("").join(chain(buf, iterator))
    return concat(buf)

def str_join(seq: t.Iterable[t.Any]) -> str:
    """Simple args to string conversion and concatenation."""
    return concat(map(str, seq))

def from_obj(cls, obj: F) -> t.Optional["_PassArg"]:
    if hasattr(obj, "jinja_pass_arg"):
        return obj.jinja_pass_arg  # type: ignore

    return None

def __getitem__(self, name: str) -> t.Any:
    blocks = self.__context.blocks[name]
    return BlockReference(name, self.__context, blocks, 0)

def get_resolve_func(self) -> str:
    target = self._context_reference_stack[-1]
    if target == "context":
        return "resolve"
    return f"{target}.resolve"

def _dict_method_all(dict_method: F) -> F:
    @functools.wraps(dict_method)
    def f_all(self: "Context") -> t.Any:
        return dict_method(self.get_all())

    return t.cast(F, f_all)

def get_all(self) -> t.Dict[str, t.Any]:
    """Return the complete context as dict including the exported
    variables.  For optimizations reasons this might not return an
    actual copy so be careful with using it.
    """
    if not self.vars:
        return self.parent
    if not self.parent:
        return self.vars
    return dict(self.parent, **self.vars)

def _render(self, context: Context) -> str:
    result = {
        "context": context.get_all(),
        "filters": sorted(self.environment.filters.keys()),
        "tests": sorted(self.environment.tests.keys()),
    }

    # Set the depth since the intent is to show the top few names.
    return pprint.pformat(result, depth=3, compact=True)

def index(self) -> int:
    """Current iteration of the loop, starting at 1."""
    return self.index0 + 1

async def length(self) -> int:  # type: ignore
    if self._length is not None:
        return self._length

    try:
        self._length = len(self._iterable)  # type: ignore
    except TypeError:
        iterable = [x async for x in self._iterator]
        self._iterator = self._to_iterator(iterable)
        self._length = len(iterable) + self.index + (self._after is not missing)

    return self._length

async def _async_call(self) -> str:
    rv = concat(
        [x async for x in self._stack[self._depth](self._context)]  # type: ignore
    )

    if self._context.eval_ctx.autoescape:
        return Markup(rv)

    return rv

def __call__(self) -> str:
    if self._context.environment.is_async:
        return self._async_call()  # type: ignore

    rv = concat(self._stack[self._depth](self._context))

    if self._context.eval_ctx.autoescape:
        return Markup(rv)

    return rv

def depth(self) -> int:
    """How many levels deep a recursive loop currently is, starting at 1."""
    return self.depth0 + 1

def __call__(self, iterable: t.Iterable[V]) -> str:
    """When iterating over nested data, render the body of the loop
    recursively with the given inner iterable data.

    The loop must have the ``recursive`` marker for this to work.
    """
    if self._recurse is None:
        raise TypeError(
            "The loop must have the 'recursive' marker to be called recursively."
        )

    return self._recurse(iterable, self._recurse, depth=self.depth)

def first(self) -> bool:
    """Whether this is the first iteration of the loop."""
    return self.index0 == 0

def previtem(self) -> t.Union[t.Any, "Undefined"]:
    """The item in the previous iteration. Undefined during the
    first iteration.
    """
    if self.first:
        return self._undefined("there is no previous item")

    return self._before

def __next__(self) -> t.Tuple[t.Any, "LoopContext"]:
    if self._after is not missing:
        rv = self._after
        self._after = missing
    else:
        rv = next(self._iterator)

    self.index0 += 1
    self._before = self._current
    self._current = rv
    return rv, self

async def _peek_next(self) -> t.Any:
    if self._after is not missing:
        return self._after

    try:
        self._after = await self._iterator.__anext__()
    except StopAsyncIteration:
        self._after = missing

    return self._after

async def nextitem(self) -> t.Union[t.Any, "Undefined"]:
    rv = await self._peek_next()

    if rv is missing:
        return self._undefined("there is no next item")

    return rv

async def _async_invoke(self, arguments: t.List[t.Any], autoescape: bool) -> str:
    rv = await self._func(*arguments)  # type: ignore

    if autoescape:
        return Markup(rv)

    return rv  # type: ignore

def _invoke(self, arguments: t.List[t.Any], autoescape: bool) -> str:
    if self._environment.is_async:
        return self._async_invoke(arguments, autoescape)  # type: ignore

    rv = self._func(*arguments)

    if autoescape:
        rv = Markup(rv)

    return rv

def _undefined_message(self) -> str:
    """Build a message about the undefined value based on how it was
    accessed.
    """
    if self._undefined_hint:
        return self._undefined_hint

    if self._undefined_obj is missing:
        return f"{self._undefined_name!r} is undefined"

    if not isinstance(self._undefined_name, str):
        return (
            f"{object_type_repr(self._undefined_obj)} has no"
            f" element {self._undefined_name!r}"
        )

    return (
        f"{object_type_repr(self._undefined_obj)!r} has no"
        f" attribute {self._undefined_name!r}"
    )

def __str__(self) -> str:
    if self._undefined_hint:
        message = f"undefined value printed: {self._undefined_hint}"

    elif self._undefined_obj is missing:
        message = self._undefined_name  # type: ignore

    else:
        message = (
            f"no such element: {object_type_repr(self._undefined_obj)}"
            f"[{self._undefined_name!r}]"
        )

    return f"{{{{ {message} }}}}"

def object_type_repr(obj: t.Any) -> str:
    """Returns the name of the object's type.  For some recognized
    singletons the name of the object is returned instead. (For
    example for `None` and `Ellipsis`).
    """
    if obj is None:
        return "None"
    elif obj is Ellipsis:
        return "Ellipsis"

    cls = type(obj)

    if cls.__module__ == "builtins":
        return f"{cls.__name__} object"

    return f"{cls.__module__}.{cls.__name__} object"

def test_sameas(value: t.Any, other: t.Any) -> bool:
    """Check if an object points to the same memory address than another
    object:

    .. sourcecode:: jinja

        {% if foo.attribute is sameas false %}
            the foo attribute really is the `False` singleton
        {% endif %}
    """
    return value is other

def describe_token(token: "Token") -> str:
    """Returns a description of the token."""
    if token.type == TOKEN_NAME:
        return token.value

    return _describe_token_type(token.type)

def describe_token_expr(expr: str) -> str:
    """Like `describe_token` but for token expressions."""
    if ":" in expr:
        type, value = expr.split(":", 1)

        if type == TOKEN_NAME:
            return value
    else:
        type = expr

    return _describe_token_type(type)

async def __aiter__(self) -> t.AsyncIterator[t.Any]:
    for _ in ():
        yield

def optimize(node: nodes.Node, environment: "Environment") -> nodes.Node:
    """The context hint can be used to perform an static optimization
    based on the context given."""
    optimizer = Optimizer(environment)
    return t.cast(nodes.Node, optimizer.visit(node))

def _log_message(undef: Undefined) -> None:
    logger.warning(  # type: ignore
        "Template variable warning: %s", undef._undefined_message
    )

def __iter__(self) -> t.Iterator[t.Any]:
    _log_message(self)
    return super().__iter__()  # type: ignore

def __bool__(self) -> bool:
    _log_message(self)
    return super().__bool__()  # type: ignore

def is_undefined(obj: t.Any) -> bool:
    """Check if the object passed is undefined.  This does nothing more than
    performing an instance check against :class:`Undefined` but looks nicer.
    This can be used for custom filters or tests that want to react to
    undefined variables.  For example a custom default filter can look like
    this::

        def default(var, default=''):
            if is_undefined(var):
                return default
            return var
    """
    from .runtime import Undefined

    return isinstance(obj, Undefined)

def reset(self) -> None:
    """Resets the bucket (unloads the bytecode)."""
    self.code: t.Optional[CodeType] = None

def bytecode_from_string(self, string: bytes) -> None:
    """Load bytecode from bytes."""
    self.load_bytecode(BytesIO(string))

def bytecode_to_string(self) -> bytes:
    """Return the bytecode as bytes."""
    out = BytesIO()
    self.write_bytecode(out)
    return out.getvalue()

def load_bytecode(self, bucket: Bucket) -> None:
    try:
        code = self.client.get(self.prefix + bucket.key)
    except Exception:
        if not self.ignore_memcache_errors:
            raise
    else:
        bucket.bytecode_from_string(code)

def dump_bytecode(self, bucket: Bucket) -> None:
    key = self.prefix + bucket.key
    value = bucket.bytecode_to_string()

    try:
        if self.timeout is not None:
            self.client.set(key, value, self.timeout)
        else:
            self.client.set(key, value)
    except Exception:
        if not self.ignore_memcache_errors:
            raise

def remove_silent() -> None:
    try:
        os.remove(f.name)
    except OSError:
        # Another process may have called clear(). On Windows,
        # another program may be holding the file open.
        pass

def get_source_checksum(self, source: str) -> str:
    """Returns a checksum for the source."""
    return sha1(source.encode("utf-8")).hexdigest()

def set_bucket(self, bucket: Bucket) -> None:
    """Put the bucket into the cache."""
    self.dump_bytecode(bucket)

def clear(self) -> None:
    # imported lazily here because google app-engine doesn't support
    # write access on the file system and the function does not exist
    # normally.
    from os import remove

    files = fnmatch.filter(os.listdir(self.directory), self.pattern % ("*",))
    for filename in files:
        try:
            remove(os.path.join(self.directory, filename))
        except OSError:
            pass

def _get_default_cache_dir(self) -> str:
    def _unsafe_dir() -> "te.NoReturn":
        raise RuntimeError(
            "Cannot determine safe temp directory.  You "
            "need to explicitly provide one."
        )

    tmpdir = tempfile.gettempdir()

    # On windows the temporary directory is used specific unless
    # explicitly forced otherwise.  We can just use that.
    if os.name == "nt":
        return tmpdir
    if not hasattr(os, "getuid"):
        _unsafe_dir()

    dirname = f"_jinja2-cache-{os.getuid()}"
    actual_dir = os.path.join(tmpdir, dirname)

    try:
        os.mkdir(actual_dir, stat.S_IRWXU)
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise
    try:
        os.chmod(actual_dir, stat.S_IRWXU)
        actual_dir_stat = os.lstat(actual_dir)
        if (
            actual_dir_stat.st_uid != os.getuid()
            or not stat.S_ISDIR(actual_dir_stat.st_mode)
            or stat.S_IMODE(actual_dir_stat.st_mode) != stat.S_IRWXU
        ):
            _unsafe_dir()
    except OSError as e:
        if e.errno != errno.EEXIST:
            raise

    actual_dir_stat = os.lstat(actual_dir)
    if (
        actual_dir_stat.st_uid != os.getuid()
        or not stat.S_ISDIR(actual_dir_stat.st_mode)
        or stat.S_IMODE(actual_dir_stat.st_mode) != stat.S_IRWXU
    ):
        _unsafe_dir()

    return actual_dir

def _unsafe_dir() -> "te.NoReturn":
    raise RuntimeError(
        "Cannot determine safe temp directory.  You "
        "need to explicitly provide one."
    )

def _default_finalize(value: t.Any) -> t.Any:
    """The default finalize function if the environment isn't
    configured with one. Or, if the environment has one, this is
    called on that function's output for constants.
    """
    return str(value)

def _make_finalize(self) -> _FinalizeInfo:
    """Build the finalize function to be used on constants and at
    runtime. Cached so it's only created once for all output nodes.

    Returns a ``namedtuple`` with the following attributes:

    ``const``
        A function to finalize constant data at compile time.

    ``src``
        Source code to output around nodes to be evaluated at
        runtime.
    """
    if self._finalize is not None:
        return self._finalize

    finalize: t.Optional[t.Callable[..., t.Any]]
    finalize = default = self._default_finalize
    src = None

    if self.environment.finalize:
        src = "environment.finalize("
        env_finalize = self.environment.finalize
        pass_arg = {
            _PassArg.context: "context",
            _PassArg.eval_context: "context.eval_ctx",
            _PassArg.environment: "environment",
        }.get(
            _PassArg.from_obj(env_finalize)  # type: ignore
        )
        finalize = None

        if pass_arg is None:

            def finalize(value: t.Any) -> t.Any:
                return default(env_finalize(value))

        else:
            src = f"{src}{pass_arg}, "

            if pass_arg == "environment":

                def finalize(value: t.Any) -> t.Any:
                    return default(env_finalize(self.environment, value))

    self._finalize = self._FinalizeInfo(finalize, src)
    return self._finalize

def _output_const_repr(self, group: t.Iterable[t.Any]) -> str:
    """Given a group of constant values converted from ``Output``
    child nodes, produce a string to write to the template module
    source.
    """
    return repr(concat(group))

def visit_Output(self, node: nodes.Output, frame: Frame) -> None:
    # If an extends is active, don't render outside a block.
    if frame.require_output_check:
        # A top-level extends is known to exist at compile time.
        if self.has_known_extends:
            return

        self.writeline("if parent_template is None:")
        self.indent()

    finalize = self._make_finalize()
    body: t.List[t.Union[t.List[t.Any], nodes.Expr]] = []

    # Evaluate constants at compile time if possible. Each item in
    # body will be either a list of static data or a node to be
    # evaluated at runtime.
    for child in node.nodes:
        try:
            if not (
                # If the finalize function requires runtime context,
                # constants can't be evaluated at compile time.
                finalize.const
                # Unless it's basic template data that won't be
                # finalized anyway.
                or isinstance(child, nodes.TemplateData)
            ):
                raise nodes.Impossible()

            const = self._output_child_to_const(child, frame, finalize)
        except (nodes.Impossible, Exception):
            # The node was not constant and needs to be evaluated at
            # runtime. Or another error was raised, which is easier
            # to debug at runtime.
            body.append(child)
            continue

        if body and isinstance(body[-1], list):
            body[-1].append(const)
        else:
            body.append([const])

    if frame.buffer is not None:
        if len(body) == 1:
            self.writeline(f"{frame.buffer}.append(")
        else:
            self.writeline(f"{frame.buffer}.extend((")

        self.indent()

    for item in body:
        if isinstance(item, list):
            # A group of constant data to join and output.
            val = self._output_const_repr(item)

            if frame.buffer is None:
                self.writeline("yield " + val)
            else:
                self.writeline(val + ",")
        else:
            if frame.buffer is None:
                self.writeline("yield ", item)
            else:
                self.newline(item)

            # A node to be evaluated at runtime.
            self._output_child_pre(item, frame, finalize)
            self.visit(item, frame)
            self._output_child_post(item, frame, finalize)

            if frame.buffer is not None:
                self.write(",")

    if frame.buffer is not None:
        self.outdent()
        self.writeline(")" if len(body) == 1 else "))")

    if frame.require_output_check:
        self.outdent()

def ignore_case(value: V) -> V:
    """For use as a postprocessor for :func:`make_attrgetter`. Converts strings
    to lowercase and returns other types as-is."""
    if isinstance(value, str):
        return t.cast(V, value.lower())

    return value

def attrgetter(item: t.Any) -> t.Any:
    for part in parts:
        item = environment.getitem(item, part)

        if default is not None and isinstance(item, Undefined):
            item = default

    if postprocess is not None:
        item = postprocess(item)

    return item

def attrgetter(item: t.Any) -> t.List[t.Any]:
    items = [None] * len(parts)

    for i, attribute_part in enumerate(parts):
        item_i = item

        for part in attribute_part:
            item_i = environment.getitem(item_i, part)

        if postprocess is not None:
            item_i = postprocess(item_i)

        items[i] = item_i

    return items

def do_forceescape(value: "t.Union[str, HasHTML]") -> Markup:
    """Enforce HTML escaping.  This will probably double escape variables."""
    if hasattr(value, "__html__"):
        value = t.cast("HasHTML", value).__html__()

    return escape(str(value))

def test_escaped(value: t.Any) -> bool:
    """Check if the value is escaped."""
    return hasattr(value, "__html__")

def do_upper(s: str) -> str:
    """Convert a value to uppercase."""
    return soft_str(s).upper()

def do_lower(s: str) -> str:
    """Convert a value to lowercase."""
    return soft_str(s).lower()

def do_capitalize(s: str) -> str:
    """Capitalize a value. The first character will be uppercase, all others
    lowercase.
    """
    return soft_str(s).capitalize()

def do_title(s: str) -> str:
    """Return a titlecased version of the value. I.e. words will start with
    uppercase letters, all remaining characters are lowercase.
    """
    return "".join(
        [
            item[0].upper() + item[1:].lower()
            for item in _word_beginning_split_re.split(soft_str(s))
            if item
        ]
    )

def do_int(value: t.Any, default: int = 0, base: int = 10) -> int:
    """Convert the value into an integer. If the
    conversion doesn't work it will return ``0``. You can
    override this default using the first parameter. You
    can also override the default base (10) in the second
    parameter, which handles input with prefixes such as
    0b, 0o and 0x for bases 2, 8 and 16 respectively.
    The base is ignored for decimal numbers and non-string values.
    """
    try:
        if isinstance(value, str):
            return int(value, base)

        return int(value)
    except (TypeError, ValueError):
        # this quirk is necessary so that "42.23"|int gives 42.
        try:
            return int(float(value))
        except (TypeError, ValueError):
            return default

def do_float(value: t.Any, default: float = 0.0) -> float:
    """Convert the value into a floating point number. If the
    conversion doesn't work it will return ``0.0``. You can
    override this default using the first parameter.
    """
    try:
        return float(value)
    except (TypeError, ValueError):
        return default

def do_format(value: str, *args: t.Any, **kwargs: t.Any) -> str:
    """Apply the given values to a `printf-style`_ format string, like
    ``string % values``.

    .. sourcecode:: jinja

        {{ "%s, %s!"|format(greeting, name) }}
        Hello, World!

    In most cases it should be more convenient and efficient to use the
    ``%`` operator or :meth:`str.format`.

    .. code-block:: text

        {{ "%s, %s!" % (greeting, name) }}
        {{ "{}, {}!".format(greeting, name) }}

    .. _printf-style: https://docs.python.org/library/stdtypes.html
        #printf-style-string-formatting
    """
    if args and kwargs:
        raise FilterArgumentError(
            "can't handle positional and keyword arguments at the same time"
        )

    return soft_str(value) % (kwargs or args)

def do_items(value: t.Union[t.Mapping[K, V], Undefined]) -> t.Iterator[t.Tuple[K, V]]:
    """Return an iterator over the ``(key, value)`` items of a mapping.

    ``x|items`` is the same as ``x.items()``, except if ``x`` is
    undefined an empty iterator is returned.

    This filter is useful if you expect the template to be rendered with
    an implementation of Jinja in another programming language that does
    not have a ``.items()`` method on its mapping type.

    .. code-block:: html+jinja

        <dl>
        {% for key, value in my_dict|items %}
            <dt>{{ key }}
            <dd>{{ value }}
        {% endfor %}
        </dl>

    .. versionadded:: 3.1
    """
    if isinstance(value, Undefined):
        return

    if not isinstance(value, abc.Mapping):
        raise TypeError("Can only get item pairs from a mapping.")

    yield from value.items()

async def auto_await(value: t.Union[t.Awaitable["V"], "V"]) -> "V":
    # Avoid a costly call to isawaitable
    if type(value) in _common_primitives:
        return t.cast("V", value)

    if inspect.isawaitable(value):
        return await t.cast("t.Awaitable[V]", value)

    return t.cast("V", value)

def sort_func(item: t.Tuple[t.Any, t.Any]) -> t.Any:
    value = item[pos]

    if not case_sensitive:
        value = ignore_case(value)

    return value

def keys(self) -> t.Iterable[t.Any]:
    """Return a list of all keys ordered by most recent usage."""
    return list(self)

def _min_or_max(
    environment: "Environment",
    value: "t.Iterable[V]",
    func: "t.Callable[..., V]",
    case_sensitive: bool,
    attribute: t.Optional[t.Union[str, int]],

def test_sequence(value: t.Any) -> bool:
    """Return true if the variable is a sequence. Sequences are variables
    that are iterable.
    """
    try:
        len(value)
        value.__getitem__
    except Exception:
        return False

    return True

def do_center(value: str, width: int = 80) -> str:
    """Centers the value in a field of a given width."""
    return soft_str(value).center(width)

def do_random(context: "Context", seq: "t.Sequence[V]") -> "t.Union[V, Undefined]":
    """Return a random item from the sequence."""
    try:
        return random.choice(seq)
    except IndexError:
        return context.environment.undefined("No random item, sequence was empty.")

def do_pprint(value: t.Any) -> str:
    """Pretty print a variable. Useful for debugging."""
    return pformat(value)

def pformat(obj: t.Any) -> str:
    """Format an object using :func:`pprint.pformat`."""
    from pprint import pformat  # type: ignore

    return pformat(obj)

def do_wordcount(s: str) -> int:
    """Count the words in that string."""
    return len(_word_re.findall(soft_str(s)))

def do_trim(value: str, chars: t.Optional[str] = None) -> str:
    """Strip leading and trailing characters, by default whitespace."""
    return soft_str(value).strip(chars)

def do_mark_safe(value: str) -> Markup:
    """Mark the value as safe which means that in an environment with automatic
    escaping enabled this variable will not be escaped.
    """
    return Markup(value)

def do_mark_unsafe(value: str) -> str:
    """Mark a value as unsafe.  This is the reverse operation for :func:`safe`."""
    return str(value)

def do_reverse(value: t.Union[str, t.Iterable[V]]) -> t.Union[str, t.Iterable[V]]:
    """Reverse the object or return an iterator that iterates over it the other
    way round.
    """
    if isinstance(value, str):
        return value[::-1]

    try:
        return reversed(value)  # type: ignore
    except TypeError:
        try:
            rv = list(value)
            rv.reverse()
            return rv
        except TypeError as e:
            raise FilterArgumentError("argument must be iterable") from e

def push_assign_tracking(self) -> None:
    """Pushes a new layer for assignment tracking."""
    self._assign_stack.append(set())

def async_variant(normal_func):  # type: ignore
    def decorator(async_func):  # type: ignore
        pass_arg = _PassArg.from_obj(normal_func)
        need_eval_context = pass_arg is None

        if pass_arg is _PassArg.environment:

            def is_async(args: t.Any) -> bool:
                return t.cast(bool, args[0].is_async)

        else:

            def is_async(args: t.Any) -> bool:
                return t.cast(bool, args[0].environment.is_async)

        # Take the doc and annotations from the sync function, but the
        # name from the async function. Pallets-Sphinx-Themes
        # build_function_directive expects __wrapped__ to point to the
        # sync function.
        async_func_attrs = ("__module__", "__name__", "__qualname__")
        normal_func_attrs = tuple(set(WRAPPER_ASSIGNMENTS).difference(async_func_attrs))

        @wraps(normal_func, assigned=normal_func_attrs)
        @wraps(async_func, assigned=async_func_attrs, updated=())
        def wrapper(*args, **kwargs):  # type: ignore
            b = is_async(args)

            if need_eval_context:
                args = args[1:]

            if b:
                return async_func(*args, **kwargs)

            return normal_func(*args, **kwargs)

        if need_eval_context:
            wrapper = pass_eval_context(wrapper)

        wrapper.jinja_async_variant = True
        return wrapper

    return decorator

def decorator(async_func):  # type: ignore
    pass_arg = _PassArg.from_obj(normal_func)
    need_eval_context = pass_arg is None

    if pass_arg is _PassArg.environment:

        def is_async(args: t.Any) -> bool:
            return t.cast(bool, args[0].is_async)

    else:

        def is_async(args: t.Any) -> bool:
            return t.cast(bool, args[0].environment.is_async)

    # Take the doc and annotations from the sync function, but the
    # name from the async function. Pallets-Sphinx-Themes
    # build_function_directive expects __wrapped__ to point to the
    # sync function.
    async_func_attrs = ("__module__", "__name__", "__qualname__")
    normal_func_attrs = tuple(set(WRAPPER_ASSIGNMENTS).difference(async_func_attrs))

    @wraps(normal_func, assigned=normal_func_attrs)
    @wraps(async_func, assigned=async_func_attrs, updated=())
    def wrapper(*args, **kwargs):  # type: ignore
        b = is_async(args)

        if need_eval_context:
            args = args[1:]

        if b:
            return async_func(*args, **kwargs)

        return normal_func(*args, **kwargs)

    if need_eval_context:
        wrapper = pass_eval_context(wrapper)

    wrapper.jinja_async_variant = True
    return wrapper

def wrapper(*args, **kwargs):  # type: ignore
    b = is_async(args)

    if need_eval_context:
        args = args[1:]

    if b:
        return async_func(*args, **kwargs)

    return normal_func(*args, **kwargs)

def optimizeconst(f: F) -> F:
    def new_func(
        self: "CodeGenerator", node: nodes.Expr, frame: "Frame", **kwargs: t.Any
    ) -> t.Any:
        # Only optimize if the frame is not volatile
        if self.optimizer is not None and not frame.eval_ctx.volatile:
            new_node = self.optimizer.visit(node, frame.eval_ctx)

            if new_node != node:
                return self.visit(new_node, frame)

        return f(self, node, frame, **kwargs)

    return update_wrapper(t.cast(F, new_func), f)

def _make_binop(op: str) -> t.Callable[["CodeGenerator", nodes.BinExpr, "Frame"], None]:
    @optimizeconst
    def visitor(self: "CodeGenerator", node: nodes.BinExpr, frame: Frame) -> None:
        if (
            self.environment.sandboxed
            and op in self.environment.intercepted_binops  # type: ignore
        ):
            self.write(f"environment.call_binop(context, {op!r}, ")
            self.visit(node.left, frame)
            self.write(", ")
            self.visit(node.right, frame)
        else:
            self.write("(")
            self.visit(node.left, frame)
            self.write(f" {op} ")
            self.visit(node.right, frame)

        self.write(")")

    return visitor

def fail(self, msg: str, lineno: int) -> "te.NoReturn":
    """Fail with a :exc:`TemplateAssertionError`."""
    raise TemplateAssertionError(msg, lineno, self.name, self.filename)

def visit_Test(self, node: nodes.Test, frame: Frame) -> None:
    with self._filter_test_common(node, frame, False):
        self.visit(node.node, frame)

def indent(self) -> None:
    """Indent by one."""
    self._indentation += 1

def outdent(self, step: int = 1) -> None:
    """Outdent by step."""
    self._indentation -= step

def visit_Include(self, node: nodes.Include, frame: Frame) -> None:
    """Handles includes."""
    if node.ignore_missing:
        self.writeline("try:")
        self.indent()

    func_name = "get_or_select_template"
    if isinstance(node.template, nodes.Const):
        if isinstance(node.template.value, str):
            func_name = "get_template"
        elif isinstance(node.template.value, (tuple, list)):
            func_name = "select_template"
    elif isinstance(node.template, (nodes.Tuple, nodes.List)):
        func_name = "select_template"

    self.writeline(f"template = environment.{func_name}(", node)
    self.visit(node.template, frame)
    self.write(f", {self.name!r})")
    if node.ignore_missing:
        self.outdent()
        self.writeline("except TemplateNotFound:")
        self.indent()
        self.writeline("pass")
        self.outdent()
        self.writeline("else:")
        self.indent()

    skip_event_yield = False
    if node.with_context:
        self.writeline(
            f"{self.choose_async()}for event in template.root_render_func("
            "template.new_context(context.get_all(), True,"
            f" {self.dump_local_context(frame)})):"
        )
    elif self.environment.is_async:
        self.writeline(
            "for event in (await template._get_default_module_async())"
            "._body_stream:"
        )
    else:
        self.writeline("yield from template._get_default_module()._body_stream")
        skip_event_yield = True

    if not skip_event_yield:
        self.indent()
        self.simple_write("event", frame)
        self.outdent()

    if node.ignore_missing:
        self.outdent()

def start_write(self, frame: Frame, node: t.Optional[nodes.Node] = None) -> None:
    """Yield or write into the frame buffer."""
    if frame.buffer is None:
        self.writeline("yield ", node)
    else:
        self.writeline(f"{frame.buffer}.append(", node)

def end_write(self, frame: Frame) -> None:
    """End the writing process started by `start_write`."""
    if frame.buffer is not None:
        self.write(")")

def write(self, x: str) -> None:
    """Write a string into the output stream."""
    if self._new_lines:
        if not self._first_write:
            self.stream.write("\n" * self._new_lines)
            self.code_lineno += self._new_lines
            if self._write_debug_info is not None:
                self.debug_info.append((self._write_debug_info, self.code_lineno))
                self._write_debug_info = None
        self._first_write = False
        self.stream.write("    " * self._indentation)
        self._new_lines = 0
    self.stream.write(x)

def visit_Macro(self, node: nodes.Macro, frame: Frame) -> None:
    macro_frame, macro_ref = self.macro_body(node, frame)
    self.newline()
    if frame.toplevel:
        if not node.name.startswith("_"):
            self.write(f"context.exported_vars.add({node.name!r})")
        self.writeline(f"context.vars[{node.name!r}] = ")
    self.write(f"{frame.symbols.ref(node.name)} = ")
    self.macro_def(macro_ref, macro_frame)

def visit_Const(self, node: nodes.Const, frame: Frame) -> None:
    val = node.as_const(frame.eval_ctx)
    if isinstance(val, float):
        self.write(str(val))
    else:
        self.write(repr(val))

def visit_Tuple(self, node: nodes.Tuple, frame: Frame) -> None:
    self.write("(")
    idx = -1
    for idx, item in enumerate(node.items):
        if idx:
            self.write(", ")
        self.visit(item, frame)
    self.write(",)" if idx == 0 else ")")

def visit_List(self, node: nodes.List, frame: Frame) -> None:
    self.write("[")
    for idx, item in enumerate(node.items):
        if idx:
            self.write(", ")
        self.visit(item, frame)
    self.write("]")

def visit_Dict(self, node: nodes.Dict, frame: Frame) -> None:
    self.write("{")
    for idx, item in enumerate(node.items):
        if idx:
            self.write(", ")
        self.visit(item.key, frame)
        self.write(": ")
        self.visit(item.value, frame)
    self.write("}")

def visit_Slice(self, node: nodes.Slice, frame: Frame) -> None:
    if node.start is not None:
        self.visit(node.start, frame)
    self.write(":")
    if node.stop is not None:
        self.visit(node.stop, frame)
    if node.step is not None:
        self.write(":")
        self.visit(node.step, frame)

def visit_Filter(self, node: nodes.Filter, frame: Frame) -> None:
    with self._filter_test_common(node, frame, True):
        # if the filter node is None we are inside a filter block
        # and want to write to the current buffer
        if node.node is not None:
            self.visit(node.node, frame)
        elif frame.eval_ctx.volatile:
            self.write(
                f"(Markup(concat({frame.buffer}))"
                f" if context.eval_ctx.autoescape else concat({frame.buffer}))"
            )
        elif frame.eval_ctx.autoescape:
            self.write(f"Markup(concat({frame.buffer}))")
        else:
            self.write(f"concat({frame.buffer})")

def visit_Keyword(self, node: nodes.Keyword, frame: Frame) -> None:
    self.write(node.key + "=")
    self.visit(node.value, frame)

def position(self, node: nodes.Node) -> str:
    """Return a human readable position for the node."""
    rv = f"line {node.lineno}"
    if self.name is not None:
        rv = f"{rv} in {self.name!r}"
    return rv

def write_expr2() -> None:
    if node.expr2 is not None:
        self.visit(node.expr2, frame)
        return

    self.write(
        f'cond_expr_undefined("the inline if-expression on'
        f" {self.position(node)} evaluated to false and no else"
        f' section was defined.")'
    )

def dump_local_context(self, frame: Frame) -> str:
    items_kv = ", ".join(
        f"{name!r}: {target}"
        for name, target in frame.symbols.dump_stores().items()
    )
    return f"{{{items_kv}}}"

def visit_Block(self, node: nodes.Block, frame: Frame) -> None:
    """Call a block and register it for the template."""
    level = 0
    if frame.toplevel:
        # if we know that we are a child template, there is no need to
        # check if we are one
        if self.has_known_extends:
            return
        if self.extends_so_far > 0:
            self.writeline("if parent_template is None:")
            self.indent()
            level += 1

    if node.scoped:
        context = self.derive_context(frame)
    else:
        context = self.get_context_ref()

    if node.required:
        self.writeline(f"if len(context.blocks[{node.name!r}]) <= 1:", node)
        self.indent()
        self.writeline(
            f'raise TemplateRuntimeError("Required block {node.name!r} not found")',
            node,
        )
        self.outdent()

    if not self.environment.is_async and frame.buffer is None:
        self.writeline(
            f"yield from context.blocks[{node.name!r}][0]({context})", node
        )
    else:
        self.writeline(
            f"{self.choose_async()}for event in"
            f" context.blocks[{node.name!r}][0]({context}):",
            node,
        )
        self.indent()
        self.simple_write("event", frame)
        self.outdent()

    self.outdent(level)

def pop_parameter_definitions(self) -> None:
    """Pops the current parameter definitions set."""
    self._param_def_block.pop()

def mark_parameter_stored(self, target: str) -> None:
    """Marks a parameter in the current parameter definitions as stored.
    This will skip the enforced undefined checks.
    """
    if self._param_def_block:
        self._param_def_block[-1].discard(target)

def visit_Import(self, node: nodes.Import, frame: Frame) -> None:
    """Visit regular imports."""
    self.writeline(f"{frame.symbols.ref(node.target)} = ", node)
    if frame.toplevel:
        self.write(f"context.vars[{node.target!r}] = ")

    self._import_common(node, frame)

    if frame.toplevel and not node.target.startswith("_"):
        self.writeline(f"context.exported_vars.discard({node.target!r})")

def visit_FromImport(self, node: nodes.FromImport, frame: Frame) -> None:
    """Visit named imports."""
    self.newline(node)
    self.write("included_template = ")
    self._import_common(node, frame)
    var_names = []
    discarded_names = []
    for name in node.names:
        if isinstance(name, tuple):
            name, alias = name
        else:
            alias = name
        self.writeline(
            f"{frame.symbols.ref(alias)} ="
            f" getattr(included_template, {name!r}, missing)"
        )
        self.writeline(f"if {frame.symbols.ref(alias)} is missing:")
        self.indent()
        message = (
            "the template {included_template.__name__!r}"
            f" (imported on {self.position(node)})"
            f" does not export the requested name {name!r}"
        )
        self.writeline(
            f"{frame.symbols.ref(alias)} = undefined(f{message!r}, name={name!r})"
        )
        self.outdent()
        if frame.toplevel:
            var_names.append(alias)
            if not alias.startswith("_"):
                discarded_names.append(alias)

    if var_names:
        if len(var_names) == 1:
            name = var_names[0]
            self.writeline(f"context.vars[{name!r}] = {frame.symbols.ref(name)}")
        else:
            names_kv = ", ".join(
                f"{name!r}: {frame.symbols.ref(name)}" for name in var_names
            )
            self.writeline(f"context.vars.update({{{names_kv}}})")
    if discarded_names:
        if len(discarded_names) == 1:
            self.writeline(f"context.exported_vars.discard({discarded_names[0]!r})")
        else:
            names_str = ", ".join(map(repr, discarded_names))
            self.writeline(
                f"context.exported_vars.difference_update(({names_str}))"
            )

def inspect_format_method(callable: t.Callable) -> t.Optional[str]:
    if not isinstance(
        callable, (types.MethodType, types.BuiltinMethodType)
    ) or callable.__name__ not in ("format", "format_map"):
        return None

    obj = callable.__self__

    if isinstance(obj, str):
        return obj

    return None

def is_safe_callable(self, obj: t.Any) -> bool:
    """Check if an object is safely callable. By default callables
    are considered safe unless decorated with :func:`unsafe`.

    This also recognizes the Django convention of setting
    ``func.alters_data = True``.
    """
    return not (
        getattr(obj, "unsafe_callable", False) or getattr(obj, "alters_data", False)
    )

def unsafe(f: F) -> F:
    """Marks a function or method as unsafe.

    .. code-block: python

        @unsafe
        def delete(self):
            pass
    """
    f.unsafe_callable = True  # type: ignore
    return f

def is_safe_attribute(self, obj: t.Any, attr: str, value: t.Any) -> bool:
    if not super().is_safe_attribute(obj, attr, value):
        return False

    return not modifies_known_mutable(obj, attr)

def _install_null(self, newstyle: t.Optional[bool] = None) -> None:
    import gettext

    translations = gettext.NullTranslations()

    if hasattr(translations, "pgettext"):
        # Python < 3.8
        pgettext = translations.pgettext  # type: ignore
    else:

        def pgettext(c: str, s: str) -> str:
            return s

    if hasattr(translations, "npgettext"):
        npgettext = translations.npgettext  # type: ignore
    else:

        def npgettext(c: str, s: str, p: str, n: int) -> str:
            return s if n == 1 else p

    self._install_callables(
        gettext=translations.gettext,
        ngettext=translations.ngettext,
        newstyle=newstyle,
        pgettext=pgettext,
        npgettext=npgettext,
    )

def parse(self, parser: "Parser") -> nodes.Output:
    lineno = parser.stream.expect("name:debug").lineno
    context = nodes.ContextReference()
    result = self.call_method("_render", [context], lineno=lineno)
    return nodes.Output([result], lineno=lineno)

def _uninstall(self, translations: "_SupportedTranslations") -> None:
    for key in ("gettext", "ngettext", "pgettext", "npgettext"):
        self.environment.globals.pop(key, None)

def _make_new_gettext(func: t.Callable[[str], str]) -> t.Callable[..., str]:
    @pass_context
    def gettext(__context: Context, __string: str, **variables: t.Any) -> str:
        rv = __context.call(func, __string)
        if __context.eval_ctx.autoescape:
            rv = Markup(rv)
        # Always treat as a format string, even if there are no
        # variables. This makes translation strings more consistent
        # and predictable. This requires escaping
        return rv % variables  # type: ignore

    return gettext

def _make_new_ngettext(func: t.Callable[[str, str, int], str]) -> t.Callable[..., str]:
    @pass_context
    def ngettext(
        __context: Context,
        __singular: str,
        __plural: str,
        __num: int,
        **variables: t.Any,
    ) -> str:
        variables.setdefault("num", __num)
        rv = __context.call(func, __singular, __plural, __num)
        if __context.eval_ctx.autoescape:
            rv = Markup(rv)
        # Always treat as a format string, see gettext comment above.
        return rv % variables  # type: ignore

    return ngettext

def _make_new_pgettext(func: t.Callable[[str, str], str]) -> t.Callable[..., str]:
    @pass_context
    def pgettext(
        __context: Context, __string_ctx: str, __string: str, **variables: t.Any
    ) -> str:
        variables.setdefault("context", __string_ctx)
        rv = __context.call(func, __string_ctx, __string)

        if __context.eval_ctx.autoescape:
            rv = Markup(rv)

        # Always treat as a format string, see gettext comment above.
        return rv % variables  # type: ignore

    return pgettext

def parse(self, parser: "Parser") -> t.Union[nodes.Node, t.List[nodes.Node]]:
    """Parse a translatable tag."""
    lineno = next(parser.stream).lineno

    context = None
    context_token = parser.stream.next_if("string")

    if context_token is not None:
        context = context_token.value

    # find all the variables referenced.  Additionally a variable can be
    # defined in the body of the trans block too, but this is checked at
    # a later state.
    plural_expr: t.Optional[nodes.Expr] = None
    plural_expr_assignment: t.Optional[nodes.Assign] = None
    num_called_num = False
    variables: t.Dict[str, nodes.Expr] = {}
    trimmed = None
    while parser.stream.current.type != "block_end":
        if variables:
            parser.stream.expect("comma")

        # skip colon for python compatibility
        if parser.stream.skip_if("colon"):
            break

        token = parser.stream.expect("name")
        if token.value in variables:
            parser.fail(
                f"translatable variable {token.value!r} defined twice.",
                token.lineno,
                exc=TemplateAssertionError,
            )

        # expressions
        if parser.stream.current.type == "assign":
            next(parser.stream)
            variables[token.value] = var = parser.parse_expression()
        elif trimmed is None and token.value in ("trimmed", "notrimmed"):
            trimmed = token.value == "trimmed"
            continue
        else:
            variables[token.value] = var = nodes.Name(token.value, "load")

        if plural_expr is None:
            if isinstance(var, nodes.Call):
                plural_expr = nodes.Name("_trans", "load")
                variables[token.value] = plural_expr
                plural_expr_assignment = nodes.Assign(
                    nodes.Name("_trans", "store"), var
                )
            else:
                plural_expr = var
            num_called_num = token.value == "num"

    parser.stream.expect("block_end")

    plural = None
    have_plural = False
    referenced = set()

    # now parse until endtrans or pluralize
    singular_names, singular = self._parse_block(parser, True)
    if singular_names:
        referenced.update(singular_names)
        if plural_expr is None:
            plural_expr = nodes.Name(singular_names[0], "load")
            num_called_num = singular_names[0] == "num"

    # if we have a pluralize block, we parse that too
    if parser.stream.current.test("name:pluralize"):
        have_plural = True
        next(parser.stream)
        if parser.stream.current.type != "block_end":
            token = parser.stream.expect("name")
            if token.value not in variables:
                parser.fail(
                    f"unknown variable {token.value!r} for pluralization",
                    token.lineno,
                    exc=TemplateAssertionError,
                )
            plural_expr = variables[token.value]
            num_called_num = token.value == "num"
        parser.stream.expect("block_end")
        plural_names, plural = self._parse_block(parser, False)
        next(parser.stream)
        referenced.update(plural_names)
    else:
        next(parser.stream)

    # register free names as simple name expressions
    for name in referenced:
        if name not in variables:
            variables[name] = nodes.Name(name, "load")

    if not have_plural:
        plural_expr = None
    elif plural_expr is None:
        parser.fail("pluralize without variables", lineno)

    if trimmed is None:
        trimmed = self.environment.policies["ext.i18n.trimmed"]
    if trimmed:
        singular = self._trim_whitespace(singular)
        if plural:
            plural = self._trim_whitespace(plural)

    node = self._make_node(
        singular,
        plural,
        context,
        variables,
        plural_expr,
        bool(referenced),
        num_called_num and have_plural,
    )
    node.set_lineno(lineno)
    if plural_expr_assignment is not None:
        return [plural_expr_assignment, node]
    else:
        return node

def next_if(self, expr: str) -> t.Optional[Token]:
    """Perform the token test and return the token if it matched.
    Otherwise the return value is `None`.
    """
    if self.current.test(expr):
        return next(self)

    return None

def find_backwards(self, offset: int) -> t.List[str]:
    try:
        for _, token_type, token_value in reversed(
            self.tokens[self.offset : offset]
        ):
            if token_type in ("comment", "linecomment"):
                try:
                    prefix, comment = token_value.split(None, 1)
                except ValueError:
                    continue
                if prefix in self.comment_tags:
                    return [comment.rstrip()]
        return []
    finally:
        self.offset = offset

def find_comments(self, lineno: int) -> t.List[str]:
    if not self.comment_tags or self.last_lineno > lineno:
        return []
    for idx, (token_lineno, _, _) in enumerate(self.tokens[self.offset :]):
        if token_lineno > lineno:
            return self.find_backwards(self.offset + idx)
    return self.find_backwards(len(self.tokens))

def count_newlines(value: str) -> int:
    """Count the number of newline characters in the string.  This is
    useful for extensions that filter a stream.
    """
    return len(newline_re.findall(value))

def __call__(self) -> str:
    if not self.used:
        self.used = True
        return ""
    return self.sep

def __str__(self) -> str:
    # for translated errors we only return the message
    if self.translated:
        return t.cast(str, self.message)

    # otherwise attach some stuff
    location = f"line {self.lineno}"
    name = self.filename or self.name
    if name:
        location = f'File "{name}", {location}'
    lines = [t.cast(str, self.message), "  " + location]

    # if the source is set, add the line to the output
    if self.source is not None:
        try:
            line = self.source.splitlines()[self.lineno - 1]
        except IndexError:
            pass
        else:
            lines.append("    " + line.strip())

    return "\n".join(lines)

def _normalize_newlines(self, value: str) -> str:
    """Replace all newlines with the configured sequence in strings
    and template data.
    """
    return newline_re.sub(self.newline_sequence, value)

def test_odd(value: int) -> bool:
    """Return true if the variable is odd."""
    return value % 2 == 1

def test_even(value: int) -> bool:
    """Return true if the variable is even."""
    return value % 2 == 0

def test_divisibleby(value: int, num: int) -> bool:
    """Check if a variable is divisible by a number."""
    return value % num == 0

def test_defined(value: t.Any) -> bool:
    """Return true if the variable is defined:

    .. sourcecode:: jinja

        {% if variable is defined %}
            value of variable: {{ variable }}
        {% else %}
            variable is not defined
        {% endif %}

    See the :func:`default` filter for a simple way to set undefined
    variables.
    """
    return not isinstance(value, Undefined)

def test_undefined(value: t.Any) -> bool:
    """Like :func:`defined` but the other way round."""
    return isinstance(value, Undefined)

def test_none(value: t.Any) -> bool:
    """Return true if the variable is none."""
    return value is None

def test_float(value: t.Any) -> bool:
    """Return true if the object is a float.

    .. versionadded:: 2.11
    """
    return isinstance(value, float)

def test_lower(value: str) -> bool:
    """Return true if the variable is lowercased."""
    return str(value).islower()

def test_upper(value: str) -> bool:
    """Return true if the variable is uppercased."""
    return str(value).isupper()

def test_string(value: t.Any) -> bool:
    """Return true if the object is a string."""
    return isinstance(value, str)

def test_mapping(value: t.Any) -> bool:
    """Return true if the object is a mapping (dict etc.).

    .. versionadded:: 2.6
    """
    return isinstance(value, abc.Mapping)

def test_number(value: t.Any) -> bool:
    """Return true if the variable is a number."""
    return isinstance(value, Number)

def open_if_exists(filename: str, mode: str = "rb") -> t.Optional[t.IO]:
    """Returns a file descriptor for the filename if that file exists,
    otherwise ``None``.
    """
    if not os.path.isfile(filename):
        return None

    return open(filename, mode)

def split_template_path(template: str) -> t.List[str]:
    """Split a path into segments and perform a sanity check.  If it detects
    '..' in the path it will raise a `TemplateNotFound` error.
    """
    pieces = []
    for piece in template.split("/"):
        if (
            os.path.sep in piece
            or (os.path.altsep and os.path.altsep in piece)
            or piece == os.path.pardir
        ):
            raise TemplateNotFound(template)
        elif piece and piece != ".":
            pieces.append(piece)
    return pieces

def uptodate() -> bool:
    try:
        return os.path.getmtime(filename) == mtime
    except OSError:
        return False

def __init__(self, capacity: int) -> None:
    self.capacity = capacity
    self._mapping: t.Dict[t.Any, t.Any] = {}
    self._queue: "te.Deque[t.Any]" = deque()
    self._postinit()

def __setstate__(self, d: t.Mapping[str, t.Any]) -> None:
    self.__dict__.update(d)
    self._postinit()

def __init__(
    self,
    load_func: t.Callable[
        [str],
        t.Optional[
            t.Union[
                str, t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]
            ]
        ],
    ],

def __contains__(self, key: t.Any) -> bool:
    """Check if a key exists in this cache."""
    return key in self._mapping

def __len__(self) -> int:
    """Return the current size of the cache."""
    return len(self._mapping)

def __delitem__(self, key: t.Any) -> None:
    """Remove an item from the cache dict.
    Raise a `KeyError` if it does not exist.
    """
    with self._wlock:
        del self._mapping[key]

        try:
            self._remove(key)
        except ValueError:
            pass

def __reversed__(self) -> t.Iterator[t.Any]:
    """Iterate over the keys in the cache dict, oldest items
    coming first.
    """
    return iter(tuple(self._queue))

def get_loader(self, template: str) -> t.Tuple[BaseLoader, str]:
    try:
        prefix, name = template.split(self.delimiter, 1)
        loader = self.mapping[prefix]
    except (ValueError, KeyError) as e:
        raise TemplateNotFound(template) from e
    return loader, name
